      de: "Ein Dorf in der Nähe von Hội An, das für seinen biologischen Anbau von Kräutern und Gemüse bekannt ist, wobei traditionelle Methoden und natürliche Düngemittel verwendet werden.",
      hu: "Egy falu Hội An közelében, amely a gyógynövények és zöldségek organikus termesztéséről ismert, hagyományos módszereket és természetes trágyát használva.",
      ro: "Un sat lângă Hội An, renumit pentru cultivarea organică a ierburilor și legumelor, folosind metode tradiționale și îngrășăminte naturale.",
      en: "A village near Hội An famous for its organic cultivation of herbs and vegetables, using traditional methods and natural fertilizers.",
      es: "Un pueblo cerca de Hội An conocido por su cultivo orgánico de hierbas y verduras, utilizando métodos tradicionales y fertilizantes naturales.",
