      ro: "Una dintre cele mai vechi grădini zoologice din lume, fondată în 1865, care găzduiește o colecție mare de animale și plante în inima orașului Ho Și Min.",
      en: "One of the oldest zoos in the world, established in 1865, home to a large collection of animals and plants in the heart of Ho Chi Minh City.",
      es: "Uno de los zoológicos más antiguos del mundo, fundado en 1865, que alberga una gran colección de animales y plantas en el corazón de Ciudad Ho Chi Minh.",
      pt: "Um dos jardins zoológicos mais antigos do mundo, fundado em 1865, que abriga uma grande coleção de animais e plantas no coração da Cidade de Ho Chi Minh.",
