    facts: {
      de: ["Beherbergt über 100 Säugetier-, Reptilien- und Vogelarten.", "Enthält auch ein Geschichtsmuseum.", "Große, alte Bäume spenden viel Schatten.", "Beliebter Freizeitort für Einheimische."],
      hu: ["Több mint 100 emlős-, hüllő- és madárfajnak ad otthont.", "Történelmi múzeumot is magában foglal.", "Nagy, öreg fák adnak sok árnyékot.", "Népszerű szabadidős hely a helyiek számára."],
      ro: ["Găzduiește peste 100 de specii de mamifere, reptile și păsări.", "Include și un muzeu de istorie.", "Copaci mari și vechi oferă umbră amplă.", "Loc popular de recreere pentru localnici."],
      en: ["Home to over 100 species of mammals, reptiles, and birds.", "Also contains a history museum.", "Large, ancient trees provide ample shade.", "A popular recreational spot for locals."],
      es: ["Alberga más de 100 especies de mamíferos, reptiles y aves.", "Incluye también un museo de historia.", "Grandes árboles antiguos proporcionan mucha sombra.", "Lugar de ocio popular para los lugareños."],
      pt: ["Abriga mais de 100 espécies de mamíferos, répteis e aves.", "Também inclui um museu de história.", "Árvores grandes e antigas proporcionam muita sombra.", "Local de lazer popular para os habitantes locais."],
      fr: ["Abrite plus de 100 espèces de mammifères, de reptiles et d'oiseaux.", "Comprend également un musée d'histoire.", "De grands arbres anciens offrent beaucoup d'ombre.", "Lieu de loisirs prisé des habitants."],
    },
    descriptionAdvanced: {
      de: "Saigon Zoo und Botanischer Garten ist ein bemerkenswertes Element der vietnamesischen Geografie und Kultur. Einer der ältesten Zoos der Welt, gegründet 1865, der eine große Sammlung von Tieren und Pflanzen im Herzen von Ho-Chi-Minh-Stadt beherbergt. Beherbergt über 100 Säugetier-, Reptilien- und Vogelarten. Enthält auch ein Geschichtsmuseum. Große, alte Bäume spenden viel Schatten. Dieses Schutzgebiet ist Teil der reichen Tier- und Pflanzenwelt Vietnams, von tropischen Wäldern bis zu Mangroven. Wie viele bedeutende Orte in Vietnam verbindet dieser Ort regionale Eigenheiten mit dem Erbe einer Jahrtausende alten Zivilisation und der französischen Kolonialzeit. Damit trägt dieser Ort zum vielseitigen Profil Vietnams bei — vom Mekong-Delta über die Halong-Bucht bis zu den Reisterrassen.",
      hu: "A(z) Saigoni Állat- és Növénykert a vietnámi földrajz és kultúra figyelemre méltó eleme. A világ egyik legrégebbi állatkertje, 1865-ben alapították, amely állatok és növények nagy gyűjteményének ad otthont Ho Si Minh-város szívében. Több mint 100 emlős-, hüllő- és madárfajnak ad otthont. Történelmi múzeumot is magában foglal. Nagy, öreg fák adnak sok árnyékot. Ez a védett terület Vietnám gazdag élővilágának része, a trópusi erdőktől a mangrovékig. Vietnám számos jelentős helyszínéhez hasonlóan ez is ötvözi a regionális sajátosságokat egy évezredes civilizáció és a francia gyarmati korszak örökségével. Ezzel a helyszín hozzájárul Vietnám sokszínű arculatához — a Mekong-deltától a Halong-öblön át a rizsteraszokig.",
      ro: "Grădina Zoologică și Botanică din Saigon este un element remarcabil al geografiei și culturii vietnameze. Una dintre cele mai vechi grădini zoologice din lume, fondată în 1865, care găzduiește o colecție mare de animale și plante în inima orașului Ho Și Min. Găzduiește peste 100 de specii de mamifere, reptile și păsări. Include și un muzeu de istorie. Copaci mari și vechi oferă umbră amplă. Această arie protejată face parte din bogata faună și floră a Vietnamului, de la pădurile tropicale până la mangrove. Asemenea multor locuri importante din Vietnam, acesta îmbină particularitățile regionale cu moștenirea unei civilizații milenare și a perioadei coloniale franceze. Astfel, acest loc contribuie la profilul variat al Vietnamului — de la Delta Mekongului, prin Golful Ha Long, până la terasele de orez.",
      en: "Saigon Zoo and Botanical Gardens is a remarkable feature of the geography and culture of Vietnam. One of the oldest zoos in the world, established in 1865, home to a large collection of animals and plants in the heart of Ho Chi Minh City. Home to over 100 species of mammals, reptiles, and birds. Also contains a history museum. Large, ancient trees provide ample shade. This protected area is part of Vietnam's rich wildlife and flora, from tropical forests to mangrove swamps. Like many notable places in Vietnam, it combines regional character with the legacy of a millennia-old civilization and the French colonial era. Thus, this place contributes to the diverse profile of Vietnam — from the Mekong Delta and Ha Long Bay to the terraced rice fields.",
      es: "El Zoológico y Jardín Botánico de Saigón es un elemento notable de la geografía y cultura vietnamitas. Es uno de los zoológicos más antiguos del mundo, fundado en 1865, y alberga una gran colección de animales y plantas en el centro de Ciudad Ho Chi Minh. Cuenta con más de 100 especies de mamíferos, reptiles y aves. También incluye un museo de historia. Grandes árboles centenarios proporcionan abundante sombra. Este espacio protegido forma parte de la rica flora y fauna de Vietnam, que abarca desde selvas tropicales hasta manglares. Como muchos lugares significativos en Vietnam, este sitio combina particularidades regionales con el legado de una civilización milenaria y la época colonial francesa. De este modo, contribuye al perfil polifacético de Vietnam, desde el delta del Mekong hasta la bahía de Halong y las terrazas de arroz.",
      pt: "O Jardim Zoológico e Botânico de Saigão é um elemento notável da geografia e cultura vietnamitas. É um dos jardins zoológicos mais antigos do mundo, fundado em 1865, abrigando uma vasta coleção de animais e plantas no coração da Cidade de Ho Chi Minh. Acomoda mais de 100 espécies de mamíferos, répteis e aves. Também inclui um museu de história. Árvores grandes e antigas proporcionam muita sombra. Esta área protegida faz parte da rica fauna e flora do Vietname, desde florestas tropicais a mangais. Tal como muitos locais significativos no Vietname, este lugar combina particularidades regionais com a herança de uma civilização milenar e do período colonial francês. Assim, este local contribui para o perfil versátil do Vietname — do Delta do Mekong à Baía de Halong e aos terraços de arroz.",
      fr: "Le zoo et le jardin botanique de Saïgon sont un élément remarquable de la géographie et de la culture vietnamiennes. Fondé en 1865, c'est l'un des plus anciens zoos du monde, abritant une vaste collection d'animaux et de plantes au cœur d'Hô Chi Minh-Ville. Il accueille plus de 100 espèces de mammifères, de reptiles et d'oiseaux. Il comprend également un musée d'histoire. De grands arbres centenaires offrent beaucoup d'ombre. Cette zone protégée fait partie de la richesse de la faune et de la flore du Vietnam, des forêts tropicales aux mangroves. Comme de nombreux lieux importants au Vietnam, cet endroit allie les particularités régionales à l'héritage d'une civilisation millénaire et de l'époque coloniale française. Ainsi, ce site contribue au profil diversifié du Vietnam — du delta du Mékong à la baie d'Halong en passant par les rizières en terrasses.",
    },
