      en: ["One of the oldest zoos in the world, established in 1865, home to a large collection of animals and plants in the heart of Ho Chi Minh City.", "Located within the Socialist Republic of Vietnam.", "Plays a role in the local identity of the region."],
      es: ["Uno de los zoológicos más antiguos del mundo, fundado en 1865, que alberga una gran colección de animales y plantas en el corazón de Ciudad Ho Chi Minh.", "Se encuentra en el territorio de la República Socialista de Vietnam.", "Desempeña un papel en la identidad local de la región."],
      pt: ["Um dos jardins zoológicos mais antigos do mundo, fundado em 1865, que abriga uma grande coleção de animais e plantas no coração da Cidade de Ho Chi Minh.", "Localiza-se no território da República Socialista do Vietname.", "Desempenha um papel na identidade local da região."],
      fr: ["L'un des plus anciens zoos du monde, fondé en 1865, abritant une vaste collection d'animaux et de plantes au cœur d'Hô Chi Minh-Ville.", "Situé sur le territoire de la République socialiste du Vietnam.", "Joue un rôle dans l'identité locale de la région."],
